--
-- Create model Child
--
CREATE TABLE "api_child" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "name" varchar(160) NOT NULL, "date_of_birth" date NOT NULL, "language" varchar(2) NOT NULL, "transition_status" varchar(30) NOT NULL);
--
-- Create model Content
--
CREATE TABLE "api_content" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "title" varchar(240) NOT NULL, "summary" text NOT NULL, "language" varchar(2) NOT NULL, "kind" varchar(20) NOT NULL, "url" varchar(200) NOT NULL, "source_url" varchar(200) NOT NULL, "review_status" varchar(30) NOT NULL, "reviewed_at" timestamp with time zone NULL, "available" boolean NOT NULL);
--
-- Create model Outbox
--
CREATE TABLE "api_outbox" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "kind" varchar(100) NOT NULL, "aggregate_id" varchar(100) NOT NULL, "actor_id" uuid NULL, "child_id" uuid NULL, "payload" jsonb NOT NULL, "status" varchar(30) NOT NULL, "attempts" integer NOT NULL CHECK ("attempts" >= 0), "available_at" timestamp with time zone NOT NULL, "completed_at" timestamp with time zone NULL, "error" varchar(240) NOT NULL);
--
-- Create model Resource
--
CREATE TABLE "api_resource" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "name" varchar(240) NOT NULL, "kind" varchar(40) NOT NULL, "location" varchar(240) NOT NULL, "summary" text NOT NULL, "url" varchar(200) NOT NULL, "verified_at" date NULL, "review_status" varchar(30) NOT NULL);
--
-- Create model Account
--
CREATE TABLE "api_account" ("password" varchar(128) NOT NULL, "last_login" timestamp with time zone NULL, "is_superuser" boolean NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "first_name" varchar(150) NOT NULL, "last_name" varchar(150) NOT NULL, "is_staff" boolean NOT NULL, "is_active" boolean NOT NULL, "date_joined" timestamp with time zone NOT NULL, "id" uuid NOT NULL PRIMARY KEY, "email" varchar(254) NOT NULL UNIQUE, "display_name" varchar(160) NOT NULL, "role" varchar(20) NOT NULL, "oidc_subject" varchar(255) NULL UNIQUE, "language" varchar(2) NOT NULL, "email_notifications" boolean NOT NULL, "push_notifications" boolean NOT NULL, "push_token" varchar(255) NOT NULL);
CREATE TABLE "api_account_groups" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "account_id" uuid NOT NULL, "group_id" integer NOT NULL);
CREATE TABLE "api_account_user_permissions" ("id" bigint NOT NULL PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY, "account_id" uuid NOT NULL, "permission_id" integer NOT NULL);
--
-- Create model Audit
--
CREATE TABLE "api_audit" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "action" varchar(100) NOT NULL, "object_id" varchar(100) NOT NULL, "purpose" varchar(200) NOT NULL, "actor_id" uuid NULL, "child_id" uuid NULL);
--
-- Create model Attachment
--
CREATE TABLE "api_attachment" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "filename" varchar(255) NOT NULL, "object_key" varchar(255) NOT NULL UNIQUE, "content_type" varchar(100) NOT NULL, "size" integer NOT NULL CHECK ("size" >= 0), "sha256" varchar(64) NOT NULL, "scan_status" varchar(30) NOT NULL, "scan_detail" varchar(240) NOT NULL, "author_id" uuid NOT NULL, "child_id" uuid NOT NULL);
--
-- Create model Appointment
--
CREATE TABLE "api_appointment" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "status" varchar(30) NOT NULL, "amount_minor" integer NOT NULL CHECK ("amount_minor" >= 0), "hold_expires_at" timestamp with time zone NOT NULL, "cancellation_reason" text NOT NULL, "booker_id" uuid NOT NULL, "child_id" uuid NOT NULL);
--
-- Create model Goal
--
CREATE TABLE "api_goal" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "title" varchar(240) NOT NULL, "description" text NOT NULL, "target_date" date NULL, "status" varchar(20) NOT NULL, "achieved_at" timestamp with time zone NULL, "author_id" uuid NOT NULL, "child_id" uuid NOT NULL);
--
-- Create model Grant
--
CREATE TABLE "api_grant" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "scopes" jsonb NOT NULL, "purpose" varchar(200) NOT NULL, "expires_at" timestamp with time zone NOT NULL, "revoked_at" timestamp with time zone NULL, "consent_version" varchar(50) NOT NULL, "child_id" uuid NOT NULL, "grantor_id" uuid NOT NULL, "recipient_id" uuid NOT NULL);
--
-- Create model Growth
--
CREATE TABLE "api_growth" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "measured_on" date NOT NULL, "weight_kg" numeric(6, 2) NOT NULL, "height_cm" numeric(6, 2) NOT NULL, "author_id" uuid NOT NULL, "child_id" uuid NOT NULL);
--
-- Create model Message
--
CREATE TABLE "api_message" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "body" text NOT NULL, "author_id" uuid NOT NULL, "child_id" uuid NOT NULL, "recipient_id" uuid NOT NULL);
--
-- Create model Notification
--
CREATE TABLE "api_notification" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "title" varchar(200) NOT NULL, "body" varchar(500) NOT NULL, "kind" varchar(50) NOT NULL, "reference" varchar(255) NOT NULL UNIQUE, "read_at" timestamp with time zone NULL, "email_status" varchar(30) NOT NULL, "push_status" varchar(30) NOT NULL, "user_id" uuid NOT NULL);
--
-- Create model Observation
--
CREATE TABLE "api_observation" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "domain" varchar(80) NOT NULL, "title" varchar(240) NOT NULL, "status" varchar(20) NOT NULL, "note" text NOT NULL, "observed_on" date NOT NULL, "author_id" uuid NOT NULL, "child_id" uuid NOT NULL);
--
-- Create model Payment
--
CREATE TABLE "api_payment" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "amount_minor" integer NOT NULL CHECK ("amount_minor" >= 0), "status" varchar(40) NOT NULL, "provider_order_id" varchar(100) NULL UNIQUE, "provider_payment_id" varchar(100) NULL UNIQUE, "refunded_minor" integer NOT NULL CHECK ("refunded_minor" >= 0), "transfer_id" varchar(100) NOT NULL, "demo" boolean NOT NULL, "appointment_id" uuid NOT NULL UNIQUE);
--
-- Create model LedgerEntry
--
CREATE TABLE "api_ledgerentry" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "reference" varchar(255) NOT NULL UNIQUE, "debit" varchar(80) NOT NULL, "credit" varchar(80) NOT NULL, "amount_minor" integer NOT NULL CHECK ("amount_minor" >= 0), "payment_id" uuid NOT NULL);
--
-- Create model PaymentEvent
--
CREATE TABLE "api_paymentevent" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "provider_event_id" varchar(255) NOT NULL UNIQUE, "kind" varchar(100) NOT NULL, "status" varchar(30) NOT NULL, "detail" varchar(240) NOT NULL, "payment_id" uuid NULL);
--
-- Create model Practitioner
--
CREATE TABLE "api_practitioner" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "specialty" varchar(160) NOT NULL, "profession" varchar(30) NOT NULL, "languages" jsonb NOT NULL, "fee_minor" integer NOT NULL CHECK ("fee_minor" >= 0), "verified" boolean NOT NULL, "status" varchar(30) NOT NULL, "bio" text NOT NULL, "registration_number" varchar(160) NOT NULL, "verification_reason" text NOT NULL, "route_account_id" varchar(100) NOT NULL, "user_id" uuid NOT NULL UNIQUE);
--
-- Add field practitioner to appointment
--
ALTER TABLE "api_appointment" ADD COLUMN "practitioner_id" uuid NOT NULL CONSTRAINT "api_appointment_practitioner_id_a13828ac_fk_api_practitioner_id" REFERENCES "api_practitioner"("id") DEFERRABLE INITIALLY DEFERRED; SET CONSTRAINTS "api_appointment_practitioner_id_a13828ac_fk_api_practitioner_id" IMMEDIATE;
--
-- Create model PrivacyRequest
--
CREATE TABLE "api_privacyrequest" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "kind" varchar(30) NOT NULL, "detail" text NOT NULL, "status" varchar(30) NOT NULL, "response" text NOT NULL, "user_id" uuid NOT NULL);
--
-- Create model ProviderApplication
--
CREATE TABLE "api_providerapplication" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "display_name" varchar(160) NOT NULL, "specialty" varchar(160) NOT NULL, "profession" varchar(30) NOT NULL, "languages" jsonb NOT NULL, "fee_minor" integer NOT NULL CHECK ("fee_minor" >= 0), "bio" text NOT NULL, "registration_number" varchar(160) NOT NULL, "status" varchar(30) NOT NULL, "review_reason" text NOT NULL, "user_id" uuid NOT NULL);
--
-- Create model Record
--
CREATE TABLE "api_record" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "kind" varchar(20) NOT NULL, "title" varchar(240) NOT NULL, "body" text NOT NULL, "status" varchar(20) NOT NULL, "signed_at" timestamp with time zone NULL, "amendment_reason" text NOT NULL, "amendment_of_id" uuid NULL, "author_id" uuid NOT NULL, "child_id" uuid NOT NULL);
--
-- Create model Referral
--
CREATE TABLE "api_referral" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "reason" text NOT NULL, "destination" varchar(240) NOT NULL, "status" varchar(20) NOT NULL, "author_id" uuid NOT NULL, "child_id" uuid NOT NULL);
--
-- Create model Refund
--
CREATE TABLE "api_refund" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "request_key" varchar(160) NOT NULL UNIQUE, "provider_refund_id" varchar(100) NULL UNIQUE, "amount_minor" integer NOT NULL CHECK ("amount_minor" >= 0), "status" varchar(30) NOT NULL, "payment_id" uuid NOT NULL);
--
-- Create model Screening
--
CREATE TABLE "api_screening" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "instrument_id" varchar(160) NOT NULL, "status" varchar(40) NOT NULL, "answers" jsonb NOT NULL, "result" jsonb NOT NULL, "review_note" text NOT NULL, "reviewed_at" timestamp with time zone NULL, "author_id" uuid NOT NULL, "child_id" uuid NOT NULL, "reviewed_by_id" uuid NULL);
--
-- Create model Slot
--
CREATE TABLE "api_slot" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "starts_at" timestamp with time zone NOT NULL, "ends_at" timestamp with time zone NOT NULL, "practitioner_id" uuid NOT NULL);
--
-- Add field slot to appointment
--
ALTER TABLE "api_appointment" ADD COLUMN "slot_id" uuid NOT NULL CONSTRAINT "api_appointment_slot_id_53d7e739_fk_api_slot_id" REFERENCES "api_slot"("id") DEFERRABLE INITIALLY DEFERRED; SET CONSTRAINTS "api_appointment_slot_id_53d7e739_fk_api_slot_id" IMMEDIATE;
--
-- Create model TherapySession
--
CREATE TABLE "api_therapysession" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "scheduled_at" timestamp with time zone NOT NULL, "note" text NOT NULL, "status" varchar(30) NOT NULL, "author_id" uuid NOT NULL, "child_id" uuid NOT NULL, "practitioner_id" uuid NOT NULL);
--
-- Create model Vaccination
--
CREATE TABLE "api_vaccination" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "name" varchar(160) NOT NULL, "administered_on" date NULL, "due_on" date NULL, "note" text NOT NULL, "author_id" uuid NOT NULL, "child_id" uuid NOT NULL);
--
-- Create model Guardianship
--
CREATE TABLE "api_guardianship" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "email" varchar(254) NOT NULL, "relationship" varchar(50) NOT NULL, "can_share" boolean NOT NULL, "scopes" jsonb NOT NULL, "status" varchar(20) NOT NULL, "revoked_at" timestamp with time zone NULL, "child_id" uuid NOT NULL, "invited_by_id" uuid NULL, "user_id" uuid NULL, CONSTRAINT "one_guardian_invitation" UNIQUE ("child_id", "email"));
--
-- Create model IdempotencyReceipt
--
CREATE TABLE "api_idempotencyreceipt" ("id" uuid NOT NULL PRIMARY KEY, "created_at" timestamp with time zone NOT NULL, "key" varchar(160) NOT NULL, "endpoint" varchar(100) NOT NULL, "body_hash" varchar(64) NOT NULL, "response" jsonb NOT NULL, "user_id" uuid NOT NULL, CONSTRAINT "one_idempotent_response" UNIQUE ("user_id", "key", "endpoint"));
--
-- Create constraint refund_within_capture on model payment
--
ALTER TABLE "api_payment" ADD CONSTRAINT "refund_within_capture" CHECK ("refunded_minor" <= ("amount_minor"));
--
-- Create constraint slot_positive_duration on model slot
--
ALTER TABLE "api_slot" ADD CONSTRAINT "slot_positive_duration" CHECK ("ends_at" > ("starts_at"));
--
-- Create constraint unique_practitioner_start on model slot
--
ALTER TABLE "api_slot" ADD CONSTRAINT "unique_practitioner_start" UNIQUE ("practitioner_id", "starts_at");
--
-- Create constraint one_active_slot_reservation on model appointment
--
CREATE UNIQUE INDEX "one_active_slot_reservation" ON "api_appointment" ("slot_id") WHERE "status" IN ('awaiting_payment', 'confirmed', 'in_progress', 'completed', 'no_show');
